import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // Extract text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = items.find(item => item.role === 'headline') || items[0];
  const textContent = textItem?.text ?? 'Journal 2';

  // Create geometry for plane card
  const width = 1.2;
  const height = 0.8;
  const geometry = new THREE.PlaneGeometry(width, height);

  // Create material with texture
  const material = new MeshBasicNodeMaterial();
  material.color.setHex(0xffffff);
  material.transparent = true;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.z = 0.01;
  group.add(mesh);

  // Load and apply texture
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    material.map = texture;
    material.needsUpdate = true;
  });

  // Create headline text
  const headline = ctx.fontAtlas.createText(textContent, {
    fontSize: 39,
    color: '#16161d',
    align: 'center'
  });
  headline.position.set(0, -0.25, 0.05);
  group.add(headline);

  // Apply parallax-scroll primitive
  const parallaxResult = ctx.primitives['parallax-scroll'](group, {
    intensity: 0.25,
    trigger: 'scroll'
  });

  // Store cleanup primitives
  const cleanupPrimitives = [parallaxResult];

  // Hover lift animation setup
  let hoverTimeline = null;
  const onHover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(group.position, {
      y: group.position.y + 0.15,
      duration: 0.5,
      ease: 'power3.out'
    }, 0);
  };

  const onHoverOut = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(group.position, {
      y: 1,
      duration: 0.6,
      ease: 'power4.out'
    }, 0);
  };

  // Press-down animation setup
  const onMouseDown = () => {
    gsap.to(group.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out'
    });
  };

  const onMouseUp = () => {
    gsap.to(group.scale, {
      x: 1,
      y: 1,
      duration: 0.3,
      ease: 'power4.out'
    });
  };

  const onClick = () => {
    ctx.emit('hub-journal.select', { card: 'journal-2' });
  };

  // Attach interaction handlers
  group.userData.handlers = {
    hover: onHover,
    hoverOut: onHoverOut,
    mouseDown: onMouseDown,
    mouseUp: onMouseUp,
    click: onClick
  };

  // Cleanup function
  group.userData.cleanup = () => {
    // Kill all GSAP timelines
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    if (hoverTimeline) hoverTimeline.kill();

    // Cleanup primitives
    for (const result of cleanupPrimitives) {
      if (result?.cleanup) result.cleanup();
    }

    // Dispose geometry and material
    geometry.dispose();
    if (material.map) material.map.dispose();
    material.dispose();
  };

  return group;
}
